-- 42 Siege Blast: shows the blast's reach with `Physics.overlap_circle`,
-- throws what it reaches, and aims the cannon with `Physics.circle_cast`.
-- The towers fall by the engine's physics. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/42-siege-blast.scene"
local BLOCKS = 45
local R = 120
local BALL_R = 15
local post_on = nav.post_all_on(SCENE)
local captions = true
local blocks = {}
local barrel, mark, reach, flash, dust, status
local flash_t = 0
local MUZZLE_X, MUZZLE_Y = -545, -220.000000

function init(entity)
    for i = 1, BLOCKS do
        local e = Entity.find_by_name("Block" .. i)
        if e then blocks[#blocks + 1] = e end
    end
    barrel = Entity.find_by_name("Barrel")
    mark = Entity.find_by_name("Mark")
    reach = Entity.find_by_name("Reach")
    flash = Entity.find_by_name("Flash")
    dust = Entity.find_by_name("Dust")
    status = Entity.find_by_name("Status")
end

local function blast(x, y)
    local hit = Physics.overlap_circle(x, y, R)
    for _, id in ipairs(hit) do
        local bx, by = Transform.get_position(id)
        local dx, dy = bx - x, by - y
        local d = math.sqrt(dx * dx + dy * dy)
        if d < 1 then dx, dy, d = 0, 1, 1 end
        local k = 1 - math.min(d / R, 1) * 0.6
        Physics.apply_impulse(id, dx / d * 2600 * k, (dy / d * 2600 + 1600) * k)
    end
    if flash then
        Transform.set_position(flash, x, y)
        flash_t = 0.25
    end
    if dust then
        Transform.set_position(dust, x, y)
        Particles.emit_burst(dust, 60)
    end
    if status then UI.set_text(status, "the blast reached " .. #hit) end
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("R") then Scene.load(SCENE) return end
    local mx, my = Input.get_mouse_world_position()

    -- What the blast would reach glows warm.
    local inside = {}
    for _, id in ipairs(Physics.overlap_circle(mx, my, R)) do inside[id] = true end
    for _, e in ipairs(blocks) do
        if inside[e] then Sprite.set_color(e, 1.45, 1.05, 0.55, 1) else Sprite.set_color(e, 1, 1, 1, 1) end
    end
    if reach then Transform.set_position(reach, mx, my) end
    if Input.is_mouse_left_just_pressed() then blast(mx, my) end

    -- The cannon aims at the mouse; a ball the size of its shot, swept from
    -- the muzzle, marks where it would first strike.
    local ax, ay = mx - MUZZLE_X, my - MUZZLE_Y
    local len = math.sqrt(ax * ax + ay * ay)
    if len > 1 then
        ax, ay = ax / len, ay / len
        if barrel then Transform.set_rotation(barrel, math.atan2 and math.atan2(ay, ax) or math.atan(ay, ax)) end
        local hit = Physics.circle_cast(MUZZLE_X + ax * 70, MUZZLE_Y + ay * 70, ax, ay, BALL_R, 2000)
        if mark then
            if hit then
                Transform.set_position(mark, MUZZLE_X + ax * (70 + hit.distance), MUZZLE_Y + ay * (70 + hit.distance))
            else
                Transform.set_position(mark, 0, -2000)
            end
        end
        if Input.is_mouse_right_just_pressed() then
            local b = Entity.spawn_prefab("SbBall")
            Transform.set_position(b, MUZZLE_X + ax * 70, MUZZLE_Y + ay * 70)
            Physics.set_velocity(b, ax * 2200, ay * 2200)
        end
    end

    if flash then
        flash_t = math.max(0, flash_t - dt)
        Sprite.set_color(flash, 1.0, 0.7, 0.3, flash_t * 3)
    end
end
